/**
 * Generates zod (TypeScript) and Pydantic (Python) code from the JSON Schemas in ../schemas.
 * JSON Schema is the single source of truth; generated files are committed and CI fails on drift.
 */
import { execFileSync } from "node:child_process";
import { mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { basename, dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { jsonSchemaToZod } from "json-schema-to-zod";

interface JsonSchema {
  title?: string;
  type?: string;
  $defs?: Record<string, JsonSchema>;
  [key: string]: unknown;
}

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const schemaDir = join(root, "schemas");
const tsOut = join(root, "src", "generated");
const pyOut = join(root, "python", "firra_contracts", "generated");
const header = "// Generated by packages/contracts/scripts/generate.ts. Do not edit.\n";

function listSchemas(dir: string): string[] {
  return readdirSync(dir)
    .sort()
    .flatMap((entry) => {
      const path = join(dir, entry);
      if (statSync(path).isDirectory()) return listSchemas(path);
      return entry.endsWith(".json") ? [path] : [];
    });
}

function lowerFirst(name: string): string {
  return name.charAt(0).toLowerCase() + name.slice(1);
}

/** json-schema-to-zod cannot follow $ref, so local `#/$defs/<Name>` references are inlined. */
function inlineLocalRefs(node: unknown, defs: Record<string, JsonSchema>, file: string): unknown {
  if (Array.isArray(node)) return node.map((item) => inlineLocalRefs(item, defs, file));
  if (node === null || typeof node !== "object") return node;
  const ref = (node as { $ref?: unknown }).$ref;
  if (typeof ref === "string") {
    const name = ref.replace(/^#\/\$defs\//, "");
    const target = defs[name];
    if (!ref.startsWith("#/$defs/") || !target) throw new Error(`${file}: unsupported $ref ${ref}`);
    return inlineLocalRefs(target, defs, file);
  }
  return Object.fromEntries(
    Object.entries(node).map(([key, value]) => [
      key,
      key === "$defs" ? undefined : inlineLocalRefs(value, defs, file),
    ]),
  );
}

function toZodModule(rawSchema: JsonSchema, file: string): string {
  const schema = inlineLocalRefs(rawSchema, rawSchema.$defs ?? {}, file) as JsonSchema;
  // A schema file either defines one root type (with a title) or only $defs (e.g. enums).
  const entries: [string, JsonSchema][] =
    schema.type === undefined && rawSchema.$defs
      ? Object.entries(rawSchema.$defs).map(([n, d]) => [
          n,
          inlineLocalRefs(d, rawSchema.$defs ?? {}, file) as JsonSchema,
        ])
      : [[schema.title ?? "", schema]];

  const parts = entries.map(([name, def]) => {
    if (!name) throw new Error(`${file}: root schema needs a title`);
    const code = jsonSchemaToZod(def, { name: lowerFirst(name), module: "esm", type: name });
    return code.replace(/^import \{ z \} from "zod"\n\n?/m, "");
  });
  return `${header}import { z } from "zod";\n\n${parts.join("\n")}`;
}

function generateTs(files: string[]): void {
  rmSync(tsOut, { recursive: true, force: true });
  const exports: string[] = [];
  for (const file of files) {
    const schema = JSON.parse(readFileSync(file, "utf8")) as JsonSchema;
    const moduleName = relative(schemaDir, file).replace(/\.json$/, "");
    const outFile = join(tsOut, `${moduleName}.ts`);
    mkdirSync(dirname(outFile), { recursive: true });
    writeFileSync(outFile, toZodModule(schema, file));
    exports.push(`export * from "./${moduleName}.js";`);
  }
  writeFileSync(join(tsOut, "index.ts"), `${header}${exports.join("\n")}\n`);
}

function generatePython(): void {
  rmSync(pyOut, { recursive: true, force: true });
  execFileSync(
    "uv",
    [
      "run",
      "--frozen",
      "datamodel-codegen",
      "--input",
      schemaDir,
      "--input-file-type",
      "jsonschema",
      "--output",
      pyOut,
      "--output-model-type",
      "pydantic_v2.BaseModel",
      "--target-python-version",
      "3.12",
      "--use-standard-collections",
      "--use-union-operator",
      "--use-title-as-name",
      "--use-subclass-enum",
      "--field-constraints",
      "--use-double-quotes",
      "--disable-timestamp",
      "--custom-file-header",
      "# Generated by packages/contracts/scripts/generate.ts. Do not edit.",
      "--formatters",
      "ruff-format",
    ],
    { cwd: root, stdio: "inherit" },
  );
}

const files = listSchemas(schemaDir);
generateTs(files);
generatePython();
process.stdout.write(
  `contracts: generated ${files.length} schemas (${files.map((f) => basename(f)).join(", ")})\n`,
);
